                top=rr
                break
            rr-=1
        # find bottom
        bottom=None
        rr=r+1
        while rr<len(lines) and lines[rr][c0] in vert+'+' and lines[rr][c1] in vert+'+':
            if lines[rr][c0]=='+' and lines[rr][c1]=='+' and is_border(lines[rr][c0:c1+1]):
                bottom=rr
                break
            rr+=1
        if top is None or bottom is None:
            continue
        key=(top,bottom,c0,c1)
        boxes.setdefault(key,[]).append((r,inner))
print('boxes',len(boxes))
# show first 30 labels
